window.LEREH_TRANSLATIONS={"Beranda | Profil Kawasan Lereh": "Home | Lereh Area Profile", "Lewati ke isi": "Skip to content", "Beranda": "Home", "Profil": "Profile", "Komoditas": "Commodities", "Panduan Kakao": "Cocoa Guide", "Simulasi Usaha": "Business Simulator", "Peta": "Maps", "Cerita Petani": "Farmer Stories", "Kelembagaan": "Institutions", "Kegiatan": "Activities", "LIVE PASAR · KAKAO": "LIVE MARKET · COCOA", "Memuat harga kakao dari penyedia data…": "Loading cocoa prices from the data provider…", "Aktifkan JavaScript untuk melihat pembaruan harga. Gunakan tautan sumber harga untuk membukanya langsung.": "Enable JavaScript to see price updates. Open the price source directly using its link.", "Tim Ekspedisi Patriot 1 Institut Teknologi Bandung": "Patriot Expedition Team 1, Bandung Institute of Technology", "Kabupaten Jayapura · Papua": "Jayapura Regency · Papua", "Profil Kawasan Transmigrasi Lereh": "Lereh Transmigration Area Profile", "Mengenal kehidupan masyarakat, potensi kakao, dan arah pengembangan agropolitan melalui data serta peta kawasan.": "Discover community life, cocoa potential, and the direction of agropolitan development through regional data and maps.", "Kenali kawasan": "Explore the area", "Jelajahi peta": "Explore the map", "Kampung di Distrik Yapsi": "Villages in Yapsi District", "Penduduk Distrik Yapsi": "Population of Yapsi District", "LQ kakao · Distrik Yapsi": "Cocoa LQ · Yapsi District", "Angka di atas memiliki cakupan Distrik Yapsi, bukan ukuran khusus tapak pengembangan agropolitan.": "These figures cover Yapsi District as a whole, rather than a specific agropolitan development site.", "Jelajahi Lereh": "Explore Lereh", "Kawasan, potensi, dan masyarakat": "The area, its potential, and its people", "PROFIL LEREH": "LEREH PROFILE", "Profil Kawasan": "Area Profile", "Lokasi, sejarah, kondisi fisik, penduduk, dan infrastruktur.": "Location, history, physical conditions, population, and infrastructure.", "Potensi Komoditas": "Commodity Potential", "Kakao, sistem agribisnis, tabel komoditas, dan grafik LQ.": "Cocoa, agribusiness systems, commodity tables, and LQ charts.", "Peta Kawasan": "Area Map", "Jelajahi wilayah dan jaringan jalan pada peta interaktif.": "Explore administrative areas and road networks on the interactive map.", "Peran masyarakat, kerja sama antarpelaku, dan arah pengembangan.": "Community roles, stakeholder collaboration, and development priorities.", "Budidaya kakao": "Cocoa cultivation", "Peta Persebaran Demplot Kakao di Distrik Yapsi": "Cocoa Demonstration Plot Locations in Yapsi District", "Peta menampilkan 10 titik CPCL/demplot sesuai data SHP yang diberikan tim. Klik titik untuk melihat nama lokasi dan koordinatnya.": "The map shows 10 CPCL/demonstration plot points from the team's SHP data. Click a point to view its location name and coordinates.", "Tampilkan semua lokasi": "Show all locations", "Titik CPCL/demplot": "CPCL/demonstration plot points", "Memuat peta persebaran demplot…": "Loading demonstration plot map…", "Daftar 10 lokasi dan koordinat": "List of 10 locations and coordinates", "Lokasi (CPCL)": "Location (CPCL)", "Lintang": "Latitude", "Bujur": "Longitude", "Lihat lokasi": "View location", "Hendra (Praktik)": "Hendra (Practical training)", "Sumber: CPCL_Demplot.shp dalam arsip Demplot.rar, data tim. Sistem koordinat: WGS 84 (EPSG:4326). Nama mengikuti atribut CPCL. Data menunjukkan titik lokasi, bukan batas atau luas kebun; status pelaksanaan masing-masing demplot tidak tercantum dalam SHP.": "Source: CPCL_Demplot.shp in Demplot.rar, supplied by the team. Coordinate system: WGS 84 (EPSG:4326). Names follow the CPCL attribute. These are location points, not farm boundaries or areas; implementation status is not recorded in the SHP.", "Petani Penerima Manfaat Pilot Project Demplot": "Farmer Beneficiaries of the Demonstration Plot Pilot Project", "Nama penerima manfaat": "Beneficiary name", "Lokasi": "Location", "Bapak Denni Sugiyantoro": "Mr Denni Sugiyantoro", "Ibu Sumiati": "Ms Sumiati", "Ibu Masitoh": "Ms Masitoh", "Bapak Diyon Renaldi": "Mr Diyon Renaldi", "Bapak Hendra": "Mr Hendra", "Bapak Juan Faldi Rahman": "Mr Juan Faldi Rahman", "Ibu Siti Nur Annisa": "Ms Siti Nur Annisa", "Ibu Sumarni": "Ms Sumarni", "Ibu Elyes Sasep Kaudin": "Ms Elyes Sasep Kaudin", "Sumber: daftar penerima manfaat pilot project demplot yang diberikan tim.": "Source: demonstration plot pilot project beneficiary list supplied by the team.", "Cerita dari kebun": "Stories from the farm", "Kakao dan masa depan petani muda": "Cocoa and the future of young farmers", "Kembali ke Yapsi, menekuni kakao": "Returning to Yapsi to grow cocoa", "Dari pekerjaan di Abepura menuju kebun sendiri, Nindiron membangun penghidupan sambil terus belajar merawat kakao. Kenali kisahnya dan pengalaman Adam dalam berbagi pengetahuan dengan petani lain.": "After working in Abepura, Nindiron returned to his own farm to build a livelihood while continuing to learn cocoa cultivation. Discover his story and Adam's experience of sharing knowledge with fellow farmers.", "Baca cerita petani": "Read farmer stories", "Jelajahi lebih jauh": "Explore further", "Belajar dan mengembangkan kakao": "Learning and developing cocoa", "Tahap budidaya, pascapanen, dan kalender kegiatan kebun.": "Cultivation stages, postharvest handling, and the farm activity calendar.", "Ubah asumsi produksi, harga, dan biaya untuk mempelajari titik impas.": "Adjust production, price, and cost assumptions to explore the break-even point.", "Kegiatan Tim": "Team Activities", "Kenali pendampingan, pelatihan, dan pengembangan teknologi.": "Discover mentoring, training, and technology development activities.", "Peta Tematik": "Thematic Maps", "Pilih peta iklim, tanah, dan topografi Yapsi–Kaureh.": "Choose climate, soil, and topographic maps of Yapsi–Kaureh.", "Berita & Kegiatan": "News & Activities", "Kabar pengembangan kakao dan kegiatan masyarakat Lereh.": "News about cocoa development and community activities in Lereh.", "Berita": "News", "31 Oktober 2026": "31 October 2026", "·  Liputan Mata Bandung": "· Coverage by Mata Bandung", "Tim Ekspedisi Patriot ITB Hubungkan Petani Kakao Papua dengan Industri Cokelat": "ITB Patriot Expedition Team Connects Papua's Cocoa Farmers with the Chocolate Industry", "Pendampingan Tim Ekspedisi Patriot ITB membuka penjajakan kemitraan antara Gapoktan Nawa Tunas Baru dan FinestCo untuk memperluas pasar kakao fermentasi Lereh, menjaga mutu, dan menyiapkan pasokan bagi industri cokelat.": "The ITB Patriot Expedition Team is helping the Nawa Tunas Baru farmer group association and FinestCo explore a partnership to expand markets for Lereh fermented cocoa, maintain quality, and prepare supplies for the chocolate industry.", "Baca selengkapnya": "Read more", "30 Oktober 2026": "30 October 2026", "·  Liputan ITB": "· Coverage by ITB", "Tim Ekspedisi Patriot ITB Bantu Petani Lereh Perluas Pasar Kakao ke Luar Papua": "ITB Patriot Expedition Team Helps Lereh Farmers Expand Cocoa Markets Beyond Papua", "Tim ITB mendampingi Gapoktan Nawa Tunas Baru menjajaki kemitraan dengan FinestCo untuk memperluas pasar kakao fermentasi. Pembelian awal lima ton direncanakan pada awal 2027.": "The ITB team is helping the Nawa Tunas Baru farmer group association explore a partnership with FinestCo to expand the fermented cocoa market. An initial purchase of five tonnes is planned for early 2027.", "Dari Kakao Lokal Menjadi Peluang Usaha!": "Turning Local Cocoa into Business Opportunities!", "Mengenal potensi keuntungan kakao dan belajar membuat produk olahan melalui kegiatan “Cacao to Cocoa” bersama Tim Ekspedisi Patriot 1 Agropolitan ITB.": "Exploring cocoa's business potential and learning to make processed products through the “Cacao to Cocoa” workshop with ITB Agropolitan Patriot Expedition Team 1.", "Kabar terbaru": "Latest updates", "Instagram · Kegiatan": "Instagram · Activities", "Sumber: Mata Bandung, ITB, dan Instagram. Foto berita: dokumentasi Tim Ekspedisi Patriot ITB. Foto kegiatan: dokumentasi yang diberikan tim.": "Sources: Mata Bandung, ITB, and Instagram. News photos: ITB Patriot Expedition Team documentation. Activity photos: documentation supplied by the team.", "Profil Kawasan Lereh": "Lereh Area Profile", "Profil Kawasan | Profil Kawasan Lereh": "Area Profile | Lereh Area Profile", "Profil kawasan": "Area profile", "Pengenalan Kawasan": "Introducing the Area", "Kawasan Transmigrasi Lereh merupakan kawasan pertanian dan perkebunan di Kabupaten Jayapura, Papua, yang mempertemukan kehidupan masyarakat lokal dan transmigran. Dalam lingkup kajian Distrik Yapsi, kegiatan ekonomi masyarakat bertumpu pada usaha tani, perkebunan rakyat, perdagangan, dan jasa skala rumah tangga. Kakao menjadi salah satu potensi utama untuk mendukung pengembangan kawasan agropolitan melalui peningkatan produksi, pengolahan hasil, pemasaran, dan penguatan kerja sama antarpelaku.": "The Lereh Transmigration Area is an agricultural and plantation area in Jayapura Regency, Papua, where indigenous communities and transmigrant families live alongside one another. Within the Yapsi District study area, livelihoods depend on farming, smallholder plantations, trade, and household-scale services. Cocoa is a key opportunity for agropolitan development through better production, processing, marketing, and stakeholder collaboration.", "Letak dan Struktur Kawasan": "Location and Settlement Structure", "Profil ini berfokus pada kawasan Lereh di Distrik Yapsi, Kabupaten Jayapura. Laporan evaluasi kawasan mencatat sembilan kampung di Distrik Yapsi, yaitu Ongan Jaya, Bumi Sahaja, Nawa Mulya, Nawa Mukti, Takwa Bangun, Purnawa Jati, Tabbeyan, Bundru, dan Kwarja. Enam kampung merupakan permukiman transmigrasi, sedangkan tiga lainnya merupakan kampung masyarakat lokal.": "This profile focuses on Lereh in Yapsi District, Jayapura Regency. The area evaluation report identifies nine villages: Ongan Jaya, Bumi Sahaja, Nawa Mulya, Nawa Mukti, Takwa Bangun, Purnawa Jati, Tabbeyan, Bundru, and Kwarja. Six are transmigration settlements, while three are indigenous community villages.", "Kampung dalam lingkup Distrik Yapsi": "Villages within Yapsi District", "Kampung": "Village", "Kategori permukiman": "Settlement category", "Kampung lokal": "Indigenous village", "Sejarah dan Perkembangan Kawasan": "History and Development", "Perkembangan kawasan Lereh berkaitan dengan pembentukan permukiman transmigrasi pada dekade 1990-an yang berdampingan dengan kampung masyarakat adat. Permukiman transmigrasi memiliki pola hunian dan lahan usaha yang relatif terencana, sementara kampung masyarakat adat berkembang mengikuti hubungan sosial, wilayah marga, dan penguasaan tanah ulayat.": "Lereh's development is linked to the establishment of transmigration settlements in the 1990s alongside indigenous villages. Transmigration settlements generally have planned residential and farming layouts, while indigenous villages developed around social relationships, clan territories, and customary land tenure.", "Perkembangan tersebut membentuk kawasan dengan masyarakat yang beragam serta kegiatan ekonomi berbasis pertanian. Dalam perjalanannya, usaha tani tidak hanya memenuhi kebutuhan rumah tangga, tetapi juga menghasilkan komoditas untuk dipasarkan ke luar kampung.": "This history has shaped a diverse community and an agriculture-based economy. Over time, farming has developed beyond household subsistence to produce commodities for markets outside the villages.", "Kondisi Fisik dan Pemanfaatan Lahan": "Physical Conditions and Land Use", "Wilayah kajian memiliki topografi yang bervariasi, mulai dari relatif datar, bergelombang, hingga berbukit ringan. Pemanfaatan lahannya mencakup permukiman, tanaman pangan, hortikultura, perkebunan rakyat, dan kawasan alami. Pada beberapa lokasi, kondisi tanah yang bersifat asam memerlukan pengelolaan budidaya yang sesuai.": "The study area has varied terrain, from relatively flat and undulating land to gently hilly areas. Land uses include settlements, food crops, horticulture, smallholder plantations, and natural areas. Acidic soils at some locations require suitable cultivation practices.", "Sungai dan sumber air permukaan berpotensi mendukung pertanian dan kebutuhan masyarakat. Namun, laporan evaluasi menunjukkan bahwa sebagian jaringan irigasi dan air bersih belum berfungsi optimal. Pemanfaatan lahan usaha juga menghadapi kendala jarak dari permukiman dan kepastian status lahan.": "Rivers and surface water sources could support farming and community needs. However, the evaluation report indicates that some irrigation and clean-water networks do not function optimally. Farm land use is also constrained by distance from settlements and uncertainty over land tenure.", "Penduduk dan Kehidupan Sosial": "Population and Community Life", "Data tahun 2024 yang disajikan dalam laporan evaluasi mencatat penduduk Distrik Yapsi sebanyak 8.025 jiwa, terdiri atas 4.214 laki-laki dan 3.811 perempuan. Angka tersebut merupakan jumlah penduduk seluruh distrik, bukan jumlah penduduk pada tapak pengembangan agropolitan tertentu.": "The evaluation report records a 2024 population of 8,025 in Yapsi District, comprising 4,214 males and 3,811 females. These figures cover the whole district, rather than any specific agropolitan development site.", "Masyarakat terdiri atas Orang Asli Papua dan transmigran yang hidup berdampingan. Pertanian dan perkebunan menjadi sumber penghidupan utama, disertai perdagangan, jasa, dan usaha rumah tangga. Kepemimpinan adat, hubungan antarmarga, serta kegiatan gotong royong memiliki peran penting dalam kehidupan sosial dan pengelolaan kawasan.": "Indigenous Papuans and transmigrant communities live alongside one another. Farming and plantations are the main livelihoods, supplemented by trade, services, and household enterprises. Customary leadership, clan relationships, and mutual assistance play important roles in community life and area management.", "Penduduk menurut kampung": "Population by village", "Distrik Yapsi · 2024 · satuan jiwa. Skala dimulai dari nol.": "Yapsi District · 2024 · people. The scale starts at zero.", "2.200 jiwa": "2,200 people", "Komposisi penduduk menurut jenis kelamin": "Population by sex", "Distrik Yapsi · 2024 · total 8.025 jiwa.": "Yapsi District · 2024 · total 8,025 people.", "Laki-laki": "Male", "4.214 jiwa · 52,51%": "4,214 people · 52.51%", "Perempuan": "Female", "3.811 jiwa · 47,49%": "3,811 people · 47.49%", "Jumlah penduduk menurut kampung · Distrik Yapsi · 2024": "Population by village · Yapsi District · 2024", "Laki-laki (jiwa)": "Male (people)", "Perempuan (jiwa)": "Female (people)", "Total (jiwa)": "Total (people)", "Aksesibilitas dan Infrastruktur Pendukung": "Accessibility and Supporting Infrastructure", "Kawasan terhubung dengan Sentani dan pusat kegiatan lainnya melalui jaringan jalan. Namun, kondisi jalan penghubung antarkampung dan sentra produksi masih menjadi kendala bagi mobilitas masyarakat, pengangkutan hasil pertanian, dan akses pelayanan dasar.": "The area is connected to Sentani and other activity centres by road. However, roads linking villages and production centres remain a constraint on mobility, agricultural transport, and access to basic services.", "Pengembangan agropolitan memerlukan dukungan jalan produksi, transportasi, irigasi, listrik, telekomunikasi, sarana pengumpulan hasil, serta fasilitas pascapanen. Keterbatasan akses pembiayaan, sarana produksi, dan pengolahan hasil juga menjadi hambatan pengembangan ekonomi masyarakat.": "Agropolitan development requires farm roads, transport, irrigation, electricity, telecommunications, produce collection facilities, and postharvest infrastructure. Limited access to finance, inputs, and processing facilities also constrains local economic development.", "Potensi Komoditas | Profil Kawasan Lereh": "Commodity Potential | Lereh Area Profile", "Jeda foto": "Pause photos", "Potensi Komoditas dan Sistem Agribisnis": "Commodity Potential and Agribusiness Systems", "Kakao merupakan komoditas basis Distrik Yapsi dengan nilai Location Quotient (LQ) 1,82 dan kontribusi ekonomi 64,6% pada tabel komoditas yang dianalisis. Nilai LQ tertinggi dimiliki kacang tanah, yaitu 3,47. Kakao diprioritaskan karena besarnya kontribusi dan potensi pengembangan rantai nilai dari budidaya hingga pengolahan.": "Cocoa is a base commodity in Yapsi District, with a Location Quotient (LQ) of 1.82 and an economic contribution of 64.6% in the analysed commodity table. Groundnuts have the highest LQ, at 3.47. Cocoa is prioritised because of its substantial contribution and potential for value chain development from cultivation to processing.", "LQ dan kontribusi ekonomi komoditas Distrik Yapsi": "Commodity LQ and economic contribution in Yapsi District", "Keterangan": "Description", "Kontribusi ekonomi": "Economic contribution", "Pisang": "Bananas", "Basis": "Base", "Cabe Rawit": "Bird's eye chillies", "Terung": "Eggplant", "Sawi": "Mustard greens", "Jagung": "Maize", "Kacang tanah": "Groundnuts", "Ubi Jalar": "Sweet potatoes", "Kakao": "Cocoa", "LQ > 1 menunjukkan komoditas basis. Kontribusi mengikuti cakupan perhitungan pada tabel sumber, bukan pangsa PDRB seluruh sektor. Delapan kontribusi yang ditampilkan berjumlah 85,6%, sehingga tabel ini tidak mewakili keseluruhan komoditas.": "LQ > 1 indicates a base commodity. Contributions follow the source table's scope, rather than the share of GRDP across all sectors. The eight displayed contributions total 85.6%, so this table does not cover all commodities.", "Sumber: hasil perhitungan yang diberikan tim, Data Analisis Pertumbuhan Ekonomi Agropolitan Yapsi (diolah). Cakupan: Distrik Yapsi.": "Source: calculations supplied by the team, Yapsi Agropolitan Economic Growth Analysis Data (processed). Coverage: Yapsi District.", "Pengembangan kakao diarahkan pada peningkatan mutu bahan tanam, pengelolaan kebun, fermentasi, pengeringan, pemasaran bersama, dan pengolahan hasil. Status basis perlu ditindaklanjuti dengan kesiapan petani, mutu pasokan, aksesibilitas, dan kemitraan pasar.": "Cocoa development focuses on better planting materials, farm management, fermentation, drying, collective marketing, and processing. Base status needs to be supported by farmer readiness, reliable quality, accessibility, and market partnerships.", "Keunggulan Komoditas Distrik Yapsi": "Commodity Advantages in Yapsi District", "Perbandingan LQ menggunakan delapan komoditas pada hasil perhitungan terbaru. Panjang batang dinormalisasi terhadap nilai tertinggi, kacang tanah (3,47).": "The LQ comparison uses eight commodities from the latest calculations. Bar lengths are normalised to the highest value, groundnuts (3.47).", "Perkembangan Produksi Kakao": "Cocoa Production Trends", "Data runtut waktu kakao Distrik Yapsi, 2020–2024": "Cocoa time series in Yapsi District, 2020–2024", "Tahun": "Year", "Luas areal (ha)": "Planted area (ha)", "Produksi (ton)": "Production (tonnes)", "Produktivitas (ton/ha)": "Productivity (tonnes/ha)", "Satuan produktivitas disesuaikan menjadi ton/ha karena angka pada gambar merupakan produksi (ton) dibagi luas (ha). Angka 0,29 ton/ha setara sekitar 290 kg/ha; nilainya dibulatkan.": "Productivity is expressed in tonnes/ha because the source figures divide production in tonnes by area in hectares. A value of 0.29 tonnes/ha is approximately 290 kg/ha; figures are rounded.", "Produksi meningkat dari 232 ton pada 2020 menjadi 733,88 ton pada 2024. CAGR produksi selama empat interval tahun mencapai 33,36% per tahun, dihitung dengan rumus [(produksi akhir / produksi awal)^(1/4) − 1] × 100%. Pertumbuhan ini berbeda dari rata-rata pertumbuhan tahunan 2022–2024 pada analisis Klassen. Luas areal bertambah dari 1.991 ha menjadi 2.545,36 ha, disertai peningkatan produktivitas.": "Production rose from 232 tonnes in 2020 to 733.88 tonnes in 2024. Over four annual intervals, production CAGR was 33.36%, calculated as [(final production / initial production)^(1/4) − 1] × 100%. This differs from the average annual growth for 2022–2024 used in the Klassen analysis. Planted area increased from 1,991 ha to 2,545.36 ha, alongside higher productivity.", "Tipologi Klassen Komoditas Perkebunan": "Klassen Typology of Plantation Commodities", "Yapsi terhadap Kabupaten Jayapura · indikator produksi · 2022–2024": "Yapsi relative to Jayapura Regency · production indicator · 2022–2024", "g Yapsi/tahun": "Yapsi growth/year", "g kabupaten/tahun": "Regency growth/year", "Kontribusi Yapsi": "Yapsi contribution", "Kontribusi kabupaten": "Regency contribution", "Kuadran": "Quadrant", "Klasifikasi": "Classification", "Maju dan tumbuh cepat (unggulan)": "Advanced and fast-growing (leading)", "Pinang": "Areca nut", "Relatif tertinggal": "Relatively lagging", "Vanili": "Vanilla", "Berkembang cepat": "Rapidly developing", "Sagu": "Sago", "Total komoditas": "All commodities", "Kakao berada pada Kuadran I karena pertumbuhan dan kontribusinya lebih tinggi daripada pembanding kabupaten. LQ kakao 1,83 menunjukkan status basis pada kelompok perkebunan ini. Pinang, vanili, dan sagu merupakan nonbasis berdasarkan LQ masing-masing yang kurang dari satu.": "Cocoa falls in Quadrant I because its growth and contribution exceed the regency benchmark. Its LQ of 1.83 indicates base status within this plantation commodity group. Areca nut, vanilla, and sago are non-base commodities, with individual LQs below one.", "Pertumbuhan adalah rata-rata per tahun; kontribusi merupakan pangsa produksi tahun 2024 dalam kelompok komoditas perkebunan yang dianalisis. LQ 1,83 dan kontribusi 97,3% pada tabel ini berbeda cakupan dengan LQ 1,82 dan kontribusi ekonomi 64,6% pada tabel lintas komoditas di atas.": "Growth is the annual average; contribution is the 2024 production share within the analysed plantation commodity group. The LQ of 1.83 and contribution of 97.3% here have a different scope from the cross-commodity LQ of 1.82 and economic contribution of 64.6% above.", "Analisis Shift Share": "Shift Share Analysis", "Perubahan produksi komoditas Yapsi, 2022–2024": "Changes in Yapsi commodity production, 2022–2024", "2022 (ton)": "2022 (tonnes)", "2024 (ton)": "2024 (tonnes)", "Perubahan (ton)": "Change (tonnes)", "g komoditas kabupaten": "Regency commodity growth", "Interpretasi D": "Interpretation of D", "Berdaya saing (D+)": "Competitive (D+)", "Kurang berdaya saing (D−)": "Less competitive (D−)", "Netral": "Neutral", "Komponen daya saing lokal kakao (D) sebesar 249,4 ton menjadi penyumbang utama kenaikan produksi sebesar 250,9 ton. Hasil ini menunjukkan pertumbuhan kakao Yapsi memiliki keunggulan relatif terhadap pertumbuhan komoditas yang sama pada wilayah pembanding, sehingga mendukung prioritas pengembangan kakao.": "Cocoa's local competitiveness component (D), at 249.4 tonnes, accounts for most of the 250.9-tonne production increase. This indicates that cocoa growth in Yapsi has a relative advantage over growth of the same commodity in the reference area, supporting cocoa development as a priority.", "N: pengaruh pertumbuhan wilayah acuan; P: pengaruh bauran komoditas; D: pengaruh daya saing lokal. Tanda kurung menunjukkan nilai negatif. Angka mengikuti pembulatan pada tabel sumber; penjumlahan nilai tampilan dapat berbeda 0,1 ton.": "N: reference-area growth effect; P: commodity mix effect; D: local competitiveness effect. Parentheses indicate negative values. Figures follow the source table's rounding; displayed sums may differ by 0.1 tonnes.", "Dari kebun ke produk": "From farm to product", "Perjalanan kakao menjadi cokelat": "The Journey from Cocoa to Chocolate", "Pengolahan berlangsung bertahap. Mutu bahan baku dan penanganan setiap tahap memengaruhi hasil akhirnya.": "Processing takes place in stages. Raw material quality and handling at every stage affect the final result.", "Panen dan pembelahan": "Harvesting and pod opening", "Pilih buah matang dan tangani buah dengan hati-hati agar biji tidak rusak.": "Select ripe pods and handle them carefully to avoid damaging the beans.", "Fermentasi": "Fermentation", "Proses pengolahan biji basah untuk membantu pembentukan mutu dan cita rasa kakao.": "Processing wet cocoa beans to help develop quality and flavour.", "Pengeringan dan sortasi": "Drying and sorting", "Keringkan di tempat bersih, lindungi dari hujan, lalu pisahkan kotoran dan biji cacat.": "Dry on clean surfaces, protect beans from rain, and remove impurities and defective beans.", "Sangrai dan penggilingan": "Roasting and grinding", "Biji disangrai, kulit dipisahkan, kemudian bagian biji digiling menjadi pasta kakao.": "Roast the beans, remove the shells, and grind the nibs into cocoa liquor.", "Pengolahan produk": "Product processing", "Pasta kakao dapat diolah lebih lanjut menjadi cokelat atau dipisahkan menjadi lemak dan bahan padat kakao.": "Cocoa liquor can be processed into chocolate or separated into cocoa butter and cocoa solids.", "Bekal usaha": "Business essentials", "Mulai dari kebun yang terkelola": "Start with a Well-managed Farm", "Kenali lahan dan bahan tanam": "Understand land and planting materials", "Perhatikan kondisi lahan, air, drainase, penaung, dan bahan tanam yang sesuai. Diskusikan kebutuhan kebun dengan petani berpengalaman atau penyuluh.": "Consider land conditions, water, drainage, shade, and suitable planting materials. Discuss farm needs with experienced farmers or extension officers.", "Rawat dan amati secara rutin": "Maintain and observe regularly", "Jaga kebersihan kebun, lakukan pemangkasan, dan amati gejala hama atau penyakit. Sesuaikan tindakan perawatan dengan kondisi tanaman.": "Keep the farm clean, prune trees, and monitor signs of pests or disease. Adapt maintenance to the condition of the plants.", "Catat biaya dan hasil": "Record costs and yields", "Pisahkan catatan uang masuk dan keluar. Catat biaya tenaga kerja, perawatan, transportasi, serta hasil penjualan untuk menilai perkembangan usaha.": "Keep separate records of income and expenses. Record labour, maintenance, and transport costs, as well as sales, to assess business progress.", "Peluang nilai tambah": "Value-added opportunities", "Lebih dari menjual biji kering": "Beyond Selling Dried Beans", "Mutu dan produk olahan": "Quality and processed products", "Fermentasi, pengeringan, dan sortasi yang konsisten dapat mendukung mutu. Pengolahan menjadi cokelat membutuhkan pengetahuan, peralatan, investasi, dan tenaga yang terampil.": "Consistent fermentation, drying, and sorting support quality. Chocolate processing requires knowledge, equipment, investment, and skilled labour.", "Pemanfaatan hasil samping": "Using by-products", "Playbook mengenalkan peluang pemanfaatan kulit buah untuk energi dan bahan alternatif. Ini merupakan potensi pengembangan yang memerlukan kajian teknis, bukan produk yang dinyatakan sudah berjalan di Lereh.": "The playbook introduces opportunities to use cocoa pod husks for energy and alternative materials. These are development opportunities requiring technical assessment, rather than products confirmed to be operating in Lereh.", "Produk dan hasil samping": "Products and by-products", "Ragam peluang dari kakao": "Opportunities from Cocoa", "Produk berikut adalah jalur pemanfaatan yang dibahas playbook. Daftar ini bukan inventaris industri yang sudah beroperasi di Lereh.": "These products are potential uses discussed in the playbook, not an inventory of industries already operating in Lereh.", "Pangan dan minuman": "Food and beverages", "Biji fermentasi, pasta, cokelat, bubuk, dan lemak kakao menjadi bagian dari rantai produk pangan.": "Fermented beans, cocoa liquor, chocolate, powder, and butter form part of the food product value chain.", "Kosmetik dan perawatan": "Cosmetics and personal care", "Lemak kakao dapat menjadi bahan formulasi pelembap, sabun, dan produk perawatan sesuai standar produk.": "Cocoa butter can be used in moisturisers, soaps, and personal-care formulations that meet the applicable product standards.", "Farmasi dan nutraseutikal": "Pharmaceuticals and nutraceuticals", "Buku membahas peluang bahan berbasis lemak dan senyawa kakao. Pengembangan memerlukan penelitian, pengujian, dan standar yang sesuai; bukan klaim manfaat pengobatan.": "The book discusses opportunities for ingredients based on cocoa butter and cocoa compounds. Development requires research, testing, and appropriate standards; this is not a claim of therapeutic benefits.", "Bioplastik": "Bioplastics", "Jalur pengembangan kulit buah mencakup pengolahan awal, hidrolisis, fermentasi menjadi asam laktat, lalu pembuatan PLA. Penerapan industri memerlukan teknologi dan kajian kelayakan.": "Pod husk processing pathways include pretreatment, hydrolysis, fermentation into lactic acid, and PLA production. Industrial application requires technology and feasibility studies.", "Residu organik dapat dikaji untuk diolah melalui fermentasi anaerob dalam biodigester sebagai sumber gas.": "Organic residues can be assessed for anaerobic digestion in a biodigester to produce gas.", "Briket dan pelet biomassa": "Biomass briquettes and pellets", "Residu dapat dikaji untuk energi panas melalui pengolahan dan pemadatan yang sesuai. Kelayakan bahan, peralatan, dan penggunaan perlu diperiksa.": "Residues can be assessed for heat generation through suitable processing and densification. Materials, equipment, and intended uses need to be evaluated.", "Panduan Kakao | Profil Kawasan Lereh": "Cocoa Guide | Lereh Area Profile", "Belajar menyiapkan kebun, merawat tanaman, dan menangani hasil panen.": "Learn to establish a farm, care for plants, and handle harvested cocoa.", "Belajar kakao": "Learning about cocoa", "Dari persiapan hingga pascapanen": "From Preparation to Postharvest", "Buka tahap yang ingin dipelajari. Ringkasan ini membantu mengenali kegiatan kebun; praktik teknis perlu menyesuaikan tanaman dan kondisi setempat.": "Open a stage to learn more. This overview introduces farm activities; technical practices must be adapted to the plants and local conditions.", "1. Kenali lokasi dan kebutuhan kebun": "1. Understand the site and farm needs", "Perhatikan tanah, air, drainase, topografi, serta tanaman penaung. Gunakan peta untuk mengenali konteks wilayah dan periksa kondisi kebun secara langsung sebelum menentukan tindakan.": "Consider soil, water, drainage, topography, and shade trees. Use maps to understand the area and inspect the farm directly before choosing actions.", "2. Siapkan lahan dan bibit": "2. Prepare land and seedlings", "Kenali asal dan kesehatan bibit. Atur titik tanam, persiapkan lubang, serta rencanakan penaung sementara dan permanen. Penanaman perlu menyesuaikan kondisi lahan dan ketersediaan air.": "Check seedling origins and health. Plan planting positions, prepare holes, and arrange temporary and permanent shade. Adapt planting to land conditions and water availability.", "3. Rawat kebun secara rutin": "3. Maintain the farm regularly", "Lakukan penyiangan sesuai kondisi gulma, gunakan mulsa, dan perhatikan kebutuhan air tanaman muda. Pemupukan disesuaikan dengan kebutuhan tanaman serta kondisi tanah.": "Weed according to local conditions, use mulch, and monitor young plants' water needs. Adapt fertilisation to plant requirements and soil conditions.", "4. Pangkas dan pantau hama": "4. Prune and monitor pests", "Pemangkasan membentuk tajuk, memperbaiki sirkulasi udara, dan menjaga masuknya cahaya. Buang tunas air serta cabang mati, sakit, atau terlalu rimbun. Amati gejala hama dan penyakit secara rutin dan diskusikan pengendaliannya dengan pendamping.": "Pruning shapes the canopy, improves airflow, and allows light through. Remove water shoots and dead, diseased, or overcrowded branches. Monitor pests and diseases regularly and discuss control measures with an adviser.", "5. Kenali perbanyakan vegetatif": "5. Learn vegetative propagation", "Playbook memperkenalkan sambung samping dan sambung pucuk untuk memanfaatkan bahan tanaman unggul. Pelajari praktiknya bersama petani berpengalaman agar pemilihan batang, entres, pengikatan, dan perawatan sambungan tepat.": "The playbook introduces side grafting and top grafting to use superior planting materials. Learn with experienced farmers to select rootstocks and scions and carry out tying and aftercare correctly.", "6. Panen buah matang": "6. Harvest ripe pods", "Pilih buah yang matang dan gunakan alat yang tajam serta bersih. Hindari merusak bantalan bunga dan buah kecil. Pisahkan buah rusak dari hasil yang baik.": "Choose ripe pods and use sharp, clean tools. Avoid damaging flower cushions and young pods. Separate damaged pods from healthy harvests.", "7. Fermentasi biji": "7. Ferment the beans", "Gunakan biji dari buah matang, wadah yang bersih dengan drainase, serta penutup yang sesuai. Playbook mencontohkan proses sekitar lima hari dengan pembalikan. Lama dan hasil proses perlu diperiksa sesuai bahan, volume, dan kondisi fermentasi.": "Use beans from ripe pods, clean containers with drainage, and suitable covers. The playbook describes a process of around five days with turning. Duration and results must be checked against the materials, volume, and fermentation conditions.", "8. Keringkan dan sortir": "8. Dry and sort", "Jemur pada alas bersih atau gunakan sarana pengeringan yang terlindung dari hujan. Balik biji agar pengeringan merata. Pisahkan benda asing serta biji berjamur, berlubang, pecah, atau tidak normal sebelum penyimpanan.": "Dry beans on clean surfaces or in facilities protected from rain. Turn them for even drying. Remove foreign matter and mouldy, holed, broken, or abnormal beans before storage.", "Kalender kegiatan kebun": "Farm Activity Calendar", "Kalender dalam playbook merupakan panduan umum. Sesuaikan dengan umur tanaman, curah hujan, varietas, dan kondisi kebun; panen mengikuti kematangan buah.": "The playbook calendar is general guidance. Adapt it to plant age, rainfall, variety, and farm conditions; harvest according to pod ripeness.", "Klik gambar untuk memperbesar.": "Click the image to enlarge.", "Awal musim hujan": "Start of the rainy season", "Prioritaskan waktu tanam ketika air mendukung pertumbuhan tanaman muda.": "Prioritise planting when water availability supports young plant growth.", "Saat lebih kering": "During drier periods", "Perhatikan penyiraman, mulsa, dan pengaturan naungan, terutama bagi bibit dan tanaman muda.": "Monitor watering, mulch, and shade management, particularly for seedlings and young plants.", "Sepanjang tahun": "Throughout the year", "Pantau kondisi kebun, atur pemangkasan, catat pekerjaan, dan panen buah yang sudah matang.": "Monitor the farm, plan pruning, record activities, and harvest ripe pods.", "Pengolahan biji menjadi cokelat": "Processing Beans into Chocolate", "Biji kering": "Dried beans", "Sangrai": "Roast", "Pisahkan kulit": "Remove shells", "Giling menjadi pasta": "Grind into cocoa liquor", "Campur bahan": "Mix ingredients", "Penghalusan": "Refining", "Cetak dan kemas": "Mould and package", "Pengolahan cokelat membutuhkan kebersihan, pengendalian proses, peralatan yang sesuai, dan keterampilan. Pasta kakao juga dapat dipres untuk menghasilkan lemak kakao dan bungkil yang kemudian diolah menjadi bubuk.": "Chocolate processing requires hygiene, process control, suitable equipment, and skills. Cocoa liquor can also be pressed into cocoa butter and press cake, which is then processed into powder.", "Simulasi Usaha Kakao | Profil Kawasan Lereh": "Cocoa Business Simulator | Lereh Area Profile", "Simulasi Usaha Kakao": "Cocoa Business Simulator", "Pelajari biaya, penerimaan, dan titik impas menggunakan asumsi yang dapat diubah.": "Explore costs, revenue, and break-even points using adjustable assumptions.", "Simulasi, bukan proyeksi": "A simulation, not a forecast", "Hitung usaha dengan asumsi sendiri": "Calculate with Your Own Assumptions", "Contoh berikut mengambil harga, produksi, dan biaya pada ilustrasi playbook. Angka bukan harga terkini, hasil survei seluruh petani, atau jaminan keuntungan. Semua komponen menggunakan periode satu tahun.": "The examples use prices, production, and costs from the playbook's illustrations. They are not current prices, survey results for all farmers, or guaranteed returns. All components cover one year.", "Mulai di sini": "Start here", "Cara mencoba simulasi": "How to Use the Simulator", "Isi kondisi usaha Anda.": "Enter your business conditions.", "Ketik angka atau geser pengaturan. Gunakan perkiraan untuk kebun yang sama selama": "Type values or move the sliders. Use estimates for the same farm over", "satu tahun": "one year", "; produksi dihitung sebagai biji kakao kering.": "; production is measured as dried cocoa beans.", "Lihat hasil langsung.": "View the results immediately.", "Penerimaan adalah uang penjualan. Total biaya adalah biaya tetap ditambah biaya variabel. Selisih positif berarti penerimaan melebihi biaya yang dimasukkan; selisih negatif berarti belum menutup biaya tersebut.": "Revenue is money from sales. Total cost is fixed plus variable costs. A positive balance means revenue exceeds the entered costs; a negative balance means these costs have not been covered.", "Coba perubahan.": "Try making changes.", "Klik": "Click", "Simpan pembanding": "Save comparison", ", lalu ubah angka untuk membandingkan hasil. Tombol contoh skenario memakai angka awal. Pada tabel perubahan harga, klik": ", then change the values to compare results. Example scenario buttons use the initial values. In the price-change table, click", "Gunakan": "Use", "untuk mencoba harga dari input saat ini. Klik": "to try a price based on the current inputs. Click", "untuk kembali ke awal dan menghapus pembanding.": "to restore the initial settings and clear the comparison.", "Belum yakin angka apa yang diisi?": "Not sure which values to enter?", "Produksi (kg/tahun)": "Production (kg/year)", "Total biji kering yang diperkirakan dijual dalam setahun. Contoh: 50 kg per bulan × 12 = 600 kg/tahun, jika panen merata.": "Estimated dried beans sold in one year. Example: 50 kg per month × 12 = 600 kg/year, if harvests are evenly distributed.", "Harga jual (Rp/kg)": "Selling price (Rp/kg)", "Harga yang diterima untuk setiap kilogram biji kering, bukan total penjualan.": "The price received for each kilogram of dried beans, not total sales.", "Biaya variabel (Rp/kg)": "Variable cost (Rp/kg)", "Biaya yang berubah mengikuti produksi, dibagi jumlah kilogram biji kering. Contoh: biaya terkait produksi Rp6.000.000 ÷ 600 kg = Rp10.000/kg.": "Costs that change with production, divided by kilograms of dried beans. Example: production-related costs of Rp6,000,000 ÷ 600 kg = Rp10,000/kg.", "Biaya tetap (Rp/tahun)": "Fixed cost (Rp/year)", "Biaya tahunan yang diasumsikan tidak berubah saat produksi berubah, misalnya sewa lahan atau penyusutan alat. Jangan masukkan biaya yang sama lagi ke biaya variabel.": "Annual costs assumed not to change when production changes, such as land rent or equipment depreciation. Do not count the same cost again under variable costs.", "Titik impas (BEP)": "Break-even point (BEP)", "Jumlah minimal produksi agar penerimaan sama dengan biaya pada asumsi yang diisi. Jika harga jual tidak melebihi biaya variabel per kg, menambah produksi belum dapat menutup biaya tetap.": "The minimum production needed for revenue to equal costs under the entered assumptions. If selling price does not exceed variable cost per kg, increasing production cannot cover fixed costs.", "Selisih ini belum menjadi laba bersih jika masih ada biaya yang belum dimasukkan. Pembanding hanya tersimpan selama halaman terbuka; memuat ulang halaman akan menghapusnya.": "This balance is not net profit if some costs have not been entered. Comparisons are stored only while the page is open; reloading clears them.", "Coba skenario:": "Try a scenario:", "Contoh awal": "Initial example", "Harga turun 20%": "Price down 20%", "Produksi naik 20%": "Production up 20%", "Atur kondisi usaha": "Set Business Conditions", "Geser atau ketik angka. Hasil langsung berubah.": "Move sliders or type values. Results update immediately.", "Produksi biji kering": "Dried bean production", "(kg/tahun)": "(kg/year)", "Harga jual": "Selling price", "Biaya variabel": "Variable cost", "Biaya tetap": "Fixed cost", "(Rp/tahun)": "(Rp/year)", "Penerimaan dan biaya tahunan": "Annual revenue and costs", "Bandingkan skenario": "Compare scenarios", "Pembanding disimpan selama halaman ini terbuka. Ubah input untuk melihat perbedaannya.": "The comparison is stored while this page is open. Change the inputs to see the difference.", "Komponen tahunan": "Annual component", "Pembanding": "Comparison", "Saat ini": "Current", "Perubahan": "Change", "Hapus pembanding": "Clear comparison", "Bagaimana jika harga berubah?": "What if Prices Change?", "Produksi dan biaya mengikuti input Anda. Pilih baris untuk mencoba harga tersebut.": "Production and costs follow your inputs. Select a row to try its price.", "Perubahan harga": "Price change", "Harga jual/kg": "Selling price/kg", "Selisih tahunan": "Annual balance", "Coba": "Try", "Penerimaan = produksi × harga. Total biaya = biaya tetap + produksi × biaya variabel per kg. BEP = biaya tetap ÷ (harga − biaya variabel per kg). Selisih belum memperhitungkan modal awal, pajak, bunga, atau komponen lain yang belum dimasukkan.": "Revenue = production × price. Total cost = fixed cost + production × variable cost per kg. BEP = fixed cost ÷ (price − variable cost per kg). The balance excludes initial capital, tax, interest, and other costs not entered.", "Kenali modal awal dan arus kas": "Understand Initial Capital and Cash Flow", "Kebutuhan untuk memulai": "What you need to start", "Perhitungkan persiapan lahan, bibit, alat, tenaga kerja, dan kebutuhan perawatan. Ilustrasi satu hektare di playbook menggunakan 625 bibit dan modal awal Rp11.949.000; harga dan kebutuhan nyata dapat berbeda.": "Allow for land preparation, seedlings, tools, labour, and maintenance. The playbook's one-hectare example uses 625 seedlings and initial capital of Rp11,949,000; actual prices and needs may differ.", "Catat uang masuk dan keluar": "Record income and expenses", "Pendapatan panen tidak selalu merata setiap bulan. Catat penjualan dan biaya agar kebutuhan kebun berikutnya dapat disiapkan.": "Harvest income is not necessarily received evenly each month. Record sales and costs to prepare for the farm's next needs.", "Sisihkan untuk keberlanjutan": "Set aside funds for sustainability", "Pertimbangkan kebutuhan perawatan, cadangan, rumah tangga, dan pengembangan usaha sesuai kemampuan. Persentase pembagian dalam buku adalah contoh, bukan ketentuan wajib.": "Consider maintenance, reserves, household needs, and business development according to your capacity. The book's allocation percentages are examples, not mandatory rules.", "Tiga cara memperbaiki hasil usaha": "Three Ways to Improve Business Results", "Perbaiki mutu": "Improve quality", "Penanganan fermentasi, pengeringan, dan sortasi membantu memenuhi kebutuhan pembeli.": "Fermentation, drying, and sorting help meet buyers' requirements.", "Perbaiki produksi": "Improve production", "Kenali bahan tanam, rawat tanaman, dan tangani gangguan budidaya sesuai kondisi kebun.": "Choose planting materials carefully, maintain plants, and address cultivation problems according to farm conditions.", "Kelola biaya": "Manage costs", "Catat penggunaan input dan tenaga kerja, serta pertimbangkan sarana bersama untuk meningkatkan efisiensi.": "Record inputs and labour, and consider shared facilities to improve efficiency.", "Peta Kawasan | Profil Kawasan Lereh": "Area Maps | Lereh Area Profile", "Peta interaktif kawasan": "Interactive area maps", "Peta Administrasi Kawasan Transmigrasi Lereh": "Administrative Map of the Lereh Transmigration Area", "Geser peta untuk menjelajahi kawasan, perbesar dengan tombol +/−, lalu klik wilayah untuk melihat namanya.": "Drag to explore the area, zoom using +/−, and click an area to see its name.", "Batas distrik (2)": "District boundaries (2)", "Batas kampung (14)": "Village boundaries (14)", "Cari distrik atau kampung": "Find a district or village", "Seluruh wilayah administrasi": "All administrative areas", "Batas wilayah SPKT (17 poligon)": "SPKT boundaries (17 polygons)", "Jalan (3 kelas)": "Roads (3 classes)", "Wilayah SPKT": "SPKT area", "Seluruh kawasan": "Entire area", "Nama wilayah": "Area name", "Lihat semua layer": "Show all layers", "Memuat batas administrasi…": "Loading administrative boundaries…", "Memuat peta…": "Loading map…", "Keterangan batas:": "Boundary notes:", "Batas distrik dan kampung berasal dari berkas Yapsi–Kaureh yang ditambahkan. Atribut kampung mencantumkan hasil delineasi batas desa 2018; Umbron memiliki catatan “Area Perlu Konfirmasi”. Batas ini tidak otomatis sama dengan batas kawasan transmigrasi. Layer SPKT lama tetap tersedia sebagai pembanding.": "District and village boundaries come from the supplied Yapsi–Kaureh files. Village attributes reference the 2018 village boundary delineation; Umbron is marked “Area Requiring Confirmation”. These boundaries do not automatically match transmigration area boundaries. The original SPKT layer remains available for comparison.", "Batas distrik": "District boundaries", "Kampung di Yapsi": "Villages in Yapsi", "Kampung di Kaureh": "Villages in Kaureh", "Batas SPKT": "SPKT boundaries", "Jalan lokal": "Local roads", "Jalan lain": "Other roads", "Jalan setapak": "Footpaths", "Cari Lereh di Google Maps ↗": "Find Lereh on Google Maps ↗", "Mengenal potensi wilayah": "Discovering regional potential", "Apa yang ada di Wilayah Kita?": "What Does Our Area Offer?", "Untuk lebih meyakinkan Anda untuk memulai berkebun kakao, mari kenali juga potensi yang ada di sekitar kita. Mulai dari kondisi wilayah tempat kita tinggal, petani yang sudah berpengalaman dan bisa membantu mengajari, dan sarana produksi yang dapat menjadi bekal awal Anda untuk segera memulai.": "To help you decide whether to start growing cocoa, explore the resources around you: the area where you live, experienced farmers who can share their knowledge, and production facilities that can help you get started.", "Bagian ini akan memperkenalkan potensi lahan di Distrik Yapsi dan Kaureh, fungsi sarana yang dapat mendukung usaha kakao, serta orang dan kelompok yang dapat membantu Anda belajar. Dengan ini, Anda bisa mulai mengenal dunia kakao dari lingkungan sendiri.": "This section introduces land potential in Yapsi and Kaureh, facilities that support cocoa businesses, and people and groups who can help you learn. Start discovering cocoa through your own surroundings.", "Kenali Kondisi yang Disukai Kakao": "Understand the Conditions Cocoa Prefers", "Kakao dapat tumbuh di lingkungan tropis yang hangat dengan air yang cukup. Tanah dan naungan juga membantu pertumbuhannya. Secara umum, kakao memerlukan": "Cocoa grows in warm tropical environments with enough water. Soil and shade also support growth. In general, cocoa requires", "4 kondisi umum": "4 general conditions", "yang perlu dipenuhi, yaitu:": "to be met:", "Kondisi": "Condition", "Artinya bagi tanaman kakao": "What it means for cocoa", "Hujan yang cukup dan tersebar": "Sufficient, well-distributed rainfall", "Kakao membutuhkan pasokan air sepanjang pertumbuhannya. Sebaran hujan sepanjang tahun penting, bukan hanya jumlah hujan tahunan.": "Cocoa needs water throughout its growth. Rainfall distribution throughout the year matters, not only the annual total.", "Tanah yang mendukung akar": "Soil that supports roots", "Tanah perlu menyediakan ruang bagi akar, menyimpan air, dan mengalirkan kelebihan air agar genangan tidak menetap.": "Soil must provide space for roots, retain water, and drain excess water to prevent persistent waterlogging.", "Lingkungan yang hangat": "A warm environment", "Suhu memengaruhi pertumbuhan kakao. Karena itu, informasi iklim menjadi bagian dari penilaian potensi wilayah.": "Temperature affects cocoa growth. Climate information therefore forms part of an assessment of regional potential.", "Naungan untuk tanaman muda": "Shade for young plants", "Pohon penaung membantu menyediakan lingkungan tumbuh bagi kakao, terutama pada awal pertumbuhannya.": "Shade trees help provide a suitable growing environment, particularly in cocoa's early stages.", "Kondisi fisik wilayah merupakan hal penting yang perlu diketahui petani untuk mengetahui komoditas yang cocok ditanam di suatu wilayah. Jangan sampai kita menanam suatu komoditas yang tidak sesuai untuk ditanam di wilayah yang kita tinggali atau miliki. Istilah “sangat sesuai” menunjukkan bahwa kondisi lahan mendukung kebutuhan tanaman menurut penilaian yang digunakan. Oleh karena itu, pemetaan akan sangat membantu kita dalam melihat di mana lahan yang sesuai atau tidak sesuai tersebut berada. Kesesuaian lahan merupakan modal awal; namun bibit dan perawatan tetap berperan penting dalam hasil kebun.": "Understanding local physical conditions helps farmers choose suitable crops. “Highly suitable” means the land meets the crop requirements under the assessment criteria used. Mapping helps identify where suitable and unsuitable land occurs. Land suitability is a starting point; seedlings and maintenance still strongly influence farm results.", "Di mana lahan yang mendukung pertumbuhan kakao? Peta di bawah membantu Anda mengenali kondisi lahan dan sebaran parameter iklim serta tanah di Distrik Yapsi dan Kaureh. Batas kampung pada peta memudahkan Anda menemukan wilayah yang sudah dikenal.": "Where is land that supports cocoa growth? The following map helps you explore land conditions and climate and soil parameters in Yapsi and Kaureh. Village boundaries make familiar areas easier to find.", "Cara membaca peta:": "How to read the map:", "layer yang tersedia menampilkan parameter iklim dan tanah untuk mendukung penilaian kesesuaian lahan. Warna pada setiap parameter belum merupakan hasil klasifikasi akhir “sangat sesuai”, “cukup sesuai”, atau “tidak sesuai”.": "available layers show climate and soil parameters to support land suitability assessment. Their colours are not final classifications of “highly suitable”, “moderately suitable”, or “unsuitable”.", "Ruang eksplorasi": "Explore the area", "Peta Kesesuaian Lahan untuk Komoditas Kakao": "Land Suitability Map for Cocoa", "Gunakan peta ini untuk melihat layer lain tanpa mengubah peta administrasi di atas. Pilih peta dasar serta parameter iklim atau tanah yang ingin dilihat.": "Use this map to explore other layers without changing the administrative map above. Select a basemap and the climate or soil parameter you want to view.", "Peta dasar": "Basemap", "Peta jalan dan wilayah sekitar": "Roads and surrounding areas", "Citra satelit": "Satellite imagery", "Latar polos untuk raster": "Plain background for rasters", "Batas kampung": "Village boundaries", "Lihat seluruh layer": "Show all layers", "Layer Iklim dan Tanah": "Climate and Soil Layers", "Pilih parameter iklim atau tanah agar warna antar-raster tidak bertumpuk. Nilai dapat dilihat dengan mengeklik lokasi di peta.": "Select one climate or soil parameter to avoid overlapping raster colours. Click a location to view its value.", "Parameter": "Parameter", "Tanpa raster": "No raster", "Kepekatan layer": "Layer opacity", "Lihat cakupan raster": "Show raster extent", "Memuat daftar raster iklim dan tanah…": "Loading climate and soil raster list…", "Klik lokasi pada peta untuk melihat nilai piksel.": "Click a location on the map to view the pixel value.", "Memuat peta tambahan…": "Loading additional map…", "Memahami Potensi Lahan Yapsi dan Kaureh": "Understanding Land Potential in Yapsi and Kaureh", "Secara keseluruhan, peta-peta di atas membantu mengenali kondisi lingkungan untuk pengembangan kakao di": "Together, these maps help identify environmental conditions for cocoa development in", "Distrik Yapsi dan Kaureh": "Yapsi and Kaureh Districts", ". Peluang pengembangan perlu dilihat pada lokasi yang mempertemukan": ". Development opportunities should focus on locations that combine", "dukungan iklim, lereng landai, dan kondisi tanah yang sesuai": "a supportive climate, gentle slopes, and suitable soils", "Faktor penting yang perlu diperhatikan:": "Important factors to consider:", "Periode kering.": "Dry period.", "Raster bulan kering yang tersedia menunjukkan kelas 0 pada seluruh piksel valid. Karena definisi kelas belum terkonfirmasi, nilai ini belum dapat diartikan sebagai 0–2 bulan kering per tahun atau langsung dinyatakan “sangat sesuai”. Sebaran hujan sepanjang tahun tetap perlu diperiksa untuk menilai kesinambungan pasokan air.": "The available dry-month raster shows class 0 across all valid pixels. As this class definition is unconfirmed, it cannot yet be interpreted as 0–2 dry months per year or directly classified as “highly suitable”. Seasonal rainfall distribution still needs checking to assess continuity of water supply.", "Curah hujan.": "Rainfall.", "Setelah dipotong mengikuti gabungan batas Yapsi–Kaureh, raster memperlihatkan rentang": "After clipping to the combined Yapsi–Kaureh boundary, the raster shows a range of", "2.339–2.721 mm/tahun": "2,339–2,721 mm/year", ". Informasi ini membantu menilai ketersediaan air, tetapi perlu dibaca bersama sebaran hujan musiman dan drainase tanah.": ". This helps assess water availability, but must be considered together with seasonal rainfall distribution and soil drainage.", "Fragmen kasar tanah.": "Coarse soil fragments.", "Kandungan fragmen kasar pada kedalaman 0–30 cm berada pada rentang": "Coarse fragment content at a depth of 0–30 cm ranges from", "dalam berkas. Kerikil dan batu perlu diperhatikan karena memengaruhi ruang tanah yang dapat dijelajahi akar. Kesesuaian setiap lokasi tetap perlu dinilai dengan kriteria yang digunakan dan pemeriksaan lapangan.": "in the data file. Gravel and stones affect the soil volume available to roots. Site suitability still needs assessment against the adopted criteria and field checks.", "Lereng landai.": "Gentle slopes.", "Lahan yang relatif datar atau berlereng landai dapat memudahkan penanaman, pemeliharaan, dan pengangkutan hasil kakao. Lokasi serta luas area tersebut perlu diperiksa melalui layer lereng dan kondisi lapangan; belum disimpulkan dari raster iklim dan tanah yang tersedia.": "Relatively flat or gently sloping land can make cocoa planting, maintenance, and transport easier. Locations and areas should be assessed using slope layers and field conditions; conclusions cannot be drawn from the available climate and soil rasters alone.", "Tekstur tanah.": "Soil texture.", "Peta menampilkan sebaran kode kelas tekstur pada kedalaman": "The map shows texture class codes at depths of", "0, 10, dan 30 cm": "0, 10, and 30 cm", ". Kode tersebut perlu dipadankan dengan nama tekstur dan kriteria kebutuhan kakao sebelum menyimpulkan tekstur mana yang sesuai atau seberapa luas penyebarannya.": ". Codes must be matched to texture names and cocoa requirements before drawing conclusions about suitability or extent.", "Peta merupakan bekal awal untuk mengenali lahan.": "Maps are a starting point for understanding land.", "Penilaian kesesuaian akhir perlu menggabungkan seluruh parameter": "A final suitability assessment must combine all parameters", "dengan kriteria yang jelas. Bibit, penaung, drainase, dan perawatan tetap berperan penting dalam keberhasilan kebun.": "using clear criteria. Seedlings, shade, drainage, and maintenance remain important to farm success.", "Yapsi dan Kaureh": "Yapsi and Kaureh", "Peta tematik potensi lahan": "Thematic Maps of Land Potential", "Kenali kondisi iklim dan tanah Yapsi–Kaureh melalui 15 peta dalam playbook. Pilih tema, lalu klik gambar untuk membuka ukuran besar. Peta ini merupakan gambar dokumen, bukan layer GIS interaktif.": "Explore Yapsi–Kaureh climate and soil conditions through 15 maps from the playbook. Select a theme and click the image to open a larger version. These are document images, not interactive GIS layers.", "Tema peta": "Map theme", "Kelerengan": "Slope", "Elevasi": "Elevation", "Arah lereng": "Aspect", "Kelerengan · gambar peta dari playbook": "Slope · map image from the playbook", "Iklim": "Climate", "Ringkasan buku mencatat periode kering yang singkat dan rentang hujan yang mendukung. Kondisi setiap kebun tetap perlu diperiksa.": "The book summary describes a short dry period and supportive rainfall levels. Conditions at each farm still need checking.", "Tanah": "Soil", "Perhatikan pH, tekstur, fragmen kasar, serta unsur dan bahan organik secara bersama, bukan satu parameter saja.": "Consider pH, texture, coarse fragments, nutrients, and organic matter together, rather than relying on one parameter.", "Topografi": "Topography", "Peta elevasi dan lereng membantu mengenali konteks pengelolaan kebun. Gambar peta ini tidak cukup untuk menetapkan kesesuaian setiap bidang lahan.": "Elevation and slope maps help understand farm management conditions. These map images alone cannot establish the suitability of individual plots.", "Cerita Petani | Profil Kawasan Lereh": "Farmer Stories | Lereh Area Profile", "Kakao dan masyarakat Lereh": "Cocoa and the People of Lereh", "Perjalanan belajar, kembali ke kebun, dan mengembangkan kakao bersama.": "Learning, returning to the farm, and developing cocoa together.", "Cerita masyarakat": "Community stories", "Dari kebun, tumbuh harapan": "Hope Grows from the Farm", "Kakao tumbuh bersama pengalaman, keterampilan, dan kerja sama masyarakat. Kenali dua perjalanan petani muda yang diceritakan dalam playbook kakao Lereh.": "Cocoa grows alongside community experience, skills, and collaboration. Discover two young farmers' journeys featured in the Lereh cocoa playbook.", "Belajar dan berbagi": "Learning and sharing", "Tumbuh dalam keluarga petani kakao, Adam sempat memilih bertani jagung setelah lulus SMK. Pendampingan dan kesempatan belajar budidaya kakao di Makassar kemudian membuka kembali minatnya pada kakao.": "Raised in a cocoa-farming family, Adam initially chose to grow maize after vocational school. Mentoring and an opportunity to study cocoa cultivation in Makassar later renewed his interest in cocoa.", "Ia mempelajari pemangkasan, pengendalian hama dan penyakit, serta sambung pucuk. Sepulangnya, pengalaman itu ia bagikan kepada petani lain. Perjalanannya memperlihatkan bagaimana keterampilan satu orang dapat menjadi ruang belajar bersama.": "He learned pruning, pest and disease management, and top grafting. On returning home, he shared these skills with other farmers. His journey shows how one person's skills can create opportunities for shared learning.", "“Jangan hanya mengejar hasil yang cepat. Tanamlah sesuatu yang bisa tumbuh bersama kita.”": "“Do not only chase quick returns. Plant something that can grow with us.”", "Kembali membangun harapan": "Returning to Build Hope", "Pekerjaan yang berat dan berisiko di tempat pengiriman barang di Pasar Abepura mendorong Nindiron kembali ke Yapsi dan menekuni kakao. Ia mengelola kebun sekitar 0,5 hektare, dengan pinang dan durian sebagai penaung.": "Demanding and risky work in goods handling at Abepura Market led Nindiron to return to Yapsi and grow cocoa. He manages around 0.5 hectares, using areca nut and durian trees for shade.", "Playbook mencatat panen sekitar 10 kilogram biji kering setiap dua minggu. Ia menerapkan fermentasi dan mengikuti pelatihan sambung pucuk, sambung samping, serta pemangkasan melalui GNTB.": "The playbook records harvests of around 10 kilograms of dried beans every two weeks. He ferments his beans and has attended top grafting, side grafting, and pruning training through GNTB.", "Serangan hama dan kesulitan memperoleh pupuk masih menjadi tantangan. Pelatihan lanjutan dan dukungan perawatan kebun menjadi bagian dari harapannya.": "Pest attacks and difficulty obtaining fertiliser remain challenges. He hopes for further training and support with farm maintenance.", "Angka tersebut menggambarkan pengalaman kebun narasumber dalam playbook, bukan rata-rata hasil kebun Lereh.": "These figures describe the interviewee's farm experience in the playbook, not average cocoa yields in Lereh.", "Kelembagaan | Profil Kawasan Lereh": "Institutions | Lereh Area Profile", "Profil kawasan / 08": "Area profile / 08", "Kelembagaan dan Tata Kelola Kawasan": "Institutions and Area Governance", "Pengelolaan kawasan melibatkan pemerintah distrik dan kampung, masyarakat adat, petani, kelompok usaha, penyuluh, serta instansi teknis. Pemerintahan kampung dan kepemimpinan adat memiliki peran yang saling berkaitan, terutama dalam pengambilan keputusan dan pengelolaan lahan.": "Area management involves district and village governments, indigenous communities, farmers, business groups, extension officers, and technical agencies. Village government and customary leadership have interconnected roles, particularly in decision-making and land management.", "Pengembangan agropolitan membutuhkan kerja sama untuk menghubungkan produksi, pendampingan, pembiayaan, pengolahan, dan pemasaran. Penguatan kelembagaan ekonomi diarahkan untuk meningkatkan kemampuan pengelolaan usaha, membangun standar mutu bersama, serta memperkuat posisi tawar petani. Pemerintah, masyarakat adat, perguruan tinggi, dan mitra usaha dapat mendukung proses tersebut sesuai perannya.": "Agropolitan development requires cooperation to connect production, mentoring, finance, processing, and marketing. Stronger economic institutions aim to improve business management, build common quality standards, and strengthen farmers' bargaining power. Government, indigenous communities, universities, and business partners can support this process within their respective roles.", "Profil kawasan / 09": "Area profile / 09", "Tantangan dan Peluang Pengembangan": "Development Challenges and Opportunities", "Tantangan kawasan meliputi keterbatasan infrastruktur, akses sarana produksi dan pembiayaan, pemanfaatan lahan yang belum optimal, persoalan legalitas lahan, serta pengolahan dan pemasaran hasil yang belum kuat. Pada komoditas kakao, peningkatan produktivitas dan konsistensi mutu menjadi kebutuhan penting.": "Challenges include limited infrastructure, access to inputs and finance, underused land, land legality issues, and weak processing and marketing. Improving cocoa productivity and maintaining consistent quality are important priorities.", "Peluang pengembangan terletak pada potensi komoditas lokal, pengalaman masyarakat dalam bertani, dan penguatan hubungan antara sentra produksi dengan pusat pelayanan. Arah pengembangan agropolitan Lereh dapat difokuskan pada perbaikan budidaya kakao, fasilitas fermentasi dan pengeringan bersama, pemasaran kolektif, peningkatan keterampilan masyarakat, serta tata kelola yang melibatkan pemerintah, masyarakat adat, petani, dan mitra usaha.": "Opportunities lie in local commodities, community farming experience, and stronger links between production centres and service centres. Lereh's agropolitan development can focus on better cocoa cultivation, shared fermentation and drying facilities, collective marketing, skills development, and governance involving government, indigenous communities, farmers, and business partners.", "Sarana pendukung": "Supporting facilities", "Dukungan dari bibit hingga penyimpanan": "Support from Seedlings to Storage", "Persemaian / nursery": "Seedling nursery", "Pembibitan dan pemeliharaan tanaman muda sebelum dipindahkan ke kebun.": "Propagation and care of young plants before transplanting to farms.", "Kotak fermentasi": "Fermentation boxes", "Wadah penanganan biji basah untuk mendukung pembentukan mutu.": "Containers for wet bean handling to support quality development.", "Tempat pengeringan / solar dryer": "Drying facilities / solar dryer", "Pengeringan biji dengan perlindungan dari hujan dan kebersihan yang terjaga.": "Drying beans in clean conditions with protection from rain.", "Gudang": "Warehouse", "Penyimpanan hasil dalam kondisi bersih, berventilasi, dan terlindung sebelum dijual.": "Clean, ventilated, protected storage before sale.", "Jenis sarana yang dikenalkan dalam playbook. Ketersediaan dan layanan penggunaannya perlu dikonfirmasi kepada pengelola.": "Facility types introduced in the playbook. Availability and terms of use must be confirmed with the operators.", "Belajar bersama": "Learning together", "Kelompok tani sebagai ruang tumbuh": "Farmer Groups as a Space for Growth", "Berbagi pengetahuan": "Sharing knowledge", "Belajar melalui pengalaman anggota lain, pendampingan, dan praktik bersama di kebun.": "Learn through other members' experience, mentoring, and practical work together on farms.", "Baku bantu": "Mutual assistance", "Kerja bersama dapat mendukung perawatan kebun, sambung tanaman, panen, dan penanganan pascapanen.": "Working together supports farm maintenance, grafting, harvesting, and postharvest handling.", "Menghubungkan usaha": "Connecting businesses", "Kelompok membantu pertukaran informasi sarana, pelatihan, pembeli, dan peluang kemitraan.": "Groups help exchange information on inputs, training, buyers, and partnership opportunities.", "GNTB diperkenalkan dalam playbook sebagai penghubung kelompok tani dan pengembangan biji kakao premium terfermentasi. Perannya mencakup pembelajaran, penguatan jejaring, serta pengembangan kakao agroforestri dan diversifikasi berkelanjutan.": "GNTB is introduced in the playbook as a link between farmer groups and the development of premium fermented cocoa beans. Its roles include learning, networking, and developing cocoa agroforestry and sustainable diversification.", "Jejaring petani": "Farmer networks", "Temukan ruang belajar di sekitar kawasan": "Find Learning Opportunities Nearby", "Kelompok tani yang diperkenalkan dalam playbook": "Farmer groups introduced in the playbook", "Wilayah": "Area", "Kelompok tani": "Farmer group", "Seebum, Distrik Kaureh": "Seebum, Kaureh District", "Lihat peta sebaran kelompok tani": "View the farmer group distribution map", "Peta dokumen dari playbook; berbeda dari batas wilayah interaktif pada halaman Peta Kawasan.": "Document map from the playbook; different from the interactive administrative boundaries on the Area Maps page.", "Kegiatan Tim | Profil Kawasan Lereh": "Team Activities | Lereh Area Profile", "Kegiatan Tim Klaster Kakao": "Cocoa Cluster Team Activities", "Pendampingan petani, penguatan kelompok, dan langkah menuju nilai tambah kakao.": "Farmer mentoring, stronger groups, and steps towards added value in cocoa.", "Belajar dan bekerja bersama": "Learning and Working Together", "Regenerasi petani": "Farmer regeneration", "Mewujudkan Kawasan Agropolitan Kakao Lereh yang berdaya saing dan berkelanjutan": "Building a Competitive and Sustainable Cocoa Agropolitan Area in Lereh", "Klaster kakao memperkenalkan peluang usaha, mengadakan workshop produk, serta menyediakan ruang belajar budidaya bagi petani muda. Dukungan digitalisasi memperkenalkan akses informasi dan promosi produk.": "The cocoa cluster introduces business opportunities, holds product workshops, and provides cultivation learning opportunities for young farmers. Digitalisation support introduces access to information and product promotion.", "Pengelolaan usaha": "Business management", "Pelatihan tata kelola kelompok": "Farmer Group Governance Training", "Pelatihan mencakup pembagian peran, manajemen usaha, serta pencatatan dan perencanaan keuangan. Pendampingan ditujukan untuk membantu penerapan dalam kegiatan kelompok sehari-hari.": "Training covers role allocation, business management, financial records, and financial planning. Mentoring helps groups apply these skills in their everyday activities.", "Mutu hasil": "Product quality", "Pendampingan pascapanen": "Postharvest Mentoring", "Tim GAP mendampingi pemilahan hasil dan perbaikan penjemuran. Playbook juga mencatat pengembangan pemanfaatan kulit kakao melalui fermentasi dan formulasi pelet pakan; ini tidak ditampilkan sebagai resep siap pakai.": "The GAP team supports produce sorting and improved drying. The playbook also records developing cocoa husk uses through fermentation and feed pellet formulation; these are not presented as ready-to-use recipes.", "Teknologi tepat guna": "Appropriate technology", "Pengenalan KakaoBrik": "Introducing KakaoBrik", "Playbook memperkenalkan alat pemecah buah untuk membantu pembukaan kakao secara lebih praktis dan mengurangi risiko kerusakan biji. Besaran dampak efisiensinya belum dinyatakan di web.": "The playbook introduces a pod-opening tool to make cocoa pod opening easier and reduce the risk of bean damage. Its efficiency impact has not been quantified on the website.", "Hilirisasi": "Downstream processing", "Membangun fondasi pengolahan": "Building a Foundation for Processing", "Kunjungan dan diskusi dilakukan untuk mempelajari rantai produksi serta kebutuhan pengetahuan, peralatan, investasi, dan tenaga. Rumah pengolahan cokelat ditempatkan sebagai arah pengembangan, bukan fasilitas yang sudah dipastikan beroperasi.": "Visits and discussions explore the production chain and the knowledge, equipment, investment, and labour needed. A chocolate processing facility is a development objective, not a facility confirmed to be operational.", "Digital Marketing & Regenerasi Petani": "Digital Marketing & Farmer Regeneration", "Menghubungkan Kakao Lereh dengan Generasi Baru": "Connecting Lereh Cocoa with a New Generation", "Kami memperkuat ekosistem kakao Lereh melalui pelatihan digital marketing, produksi konten, personal branding, dan komunikasi bisnis bagi petani, generasi muda, kelompok tani (Poktan), serta gabungan kelompok tani (Gapoktan). Pendampingan dilakukan melalui praktik langsung untuk mengangkat cerita petani, potensi kebun, dan kualitas kakao Lereh ke ruang digital. Bersama sekolah dan komunitas lokal, program ini juga menumbuhkan ketertarikan generasi muda terhadap kakao sekaligus menyiapkan kader pemasaran yang mampu memperluas jejaring, membangun kepercayaan, dan menggerakkan keberlanjutan kakao dari kampung.": "We strengthen Lereh's cocoa ecosystem through training in digital marketing, content production, personal branding, and business communication for farmers, young people, farmer groups (Poktan), and farmer group associations (Gapoktan). Hands-on mentoring brings farmers' stories, farm potential, and Lereh cocoa quality into digital spaces. Together with schools and local communities, the programme also encourages young people's interest in cocoa and prepares marketing advocates who can expand networks, build trust, and support cocoa sustainability from their villages.", "Pengembangan Kawasan Transmigrasi Lereh diarahkan untuk mewujudkan agropolitan kakao terintegrasi dari hulu hingga hilir, dengan fokus peningkatan produksi biji kakao melalui perluasan lahan potensial, pembangunan demplot percontohan, dan sekolah lapang bagi petani pemula. Peta distrik dan analisis kesesuaian lahan menjadi dasar pengembangan areal budidaya kakao pada lahan berkategori sangat sesuai guna memenuhi kebutuhan pasar yang lebih luas. Hilirisasi didorong melalui workshop pembuatan cokelat sederhana langsung dari biji kakao hasil kebun serta pengembangan kemitraan pasar baru. Luaran lainnya meliputi buku “Mulai Dari Kebun, Menggali Peluang Cokelat – Panduan Praktis Berkebun Kakao di Tanah Papua”, Dokumen Rencana Pengembangan Kawasan Agropolitan Lereh Berbasis Komoditas Unggulan Kakao Tahun 2027–2029, dan Website Kawasan Transmigrasi Lereh. Keberlanjutan program diperkuat melalui Pokja Agropolitan yang dipimpin Dinas Transmigrasi sebagai koordinator pengembangan kawasan.": "Development of the Lereh Transmigration Area aims to establish an integrated cocoa agropolitan system from upstream to downstream. Priorities include increasing bean production through suitable land expansion, demonstration plots, and field schools for new farmers. District maps and land suitability analysis guide cultivation expansion on highly suitable land to serve wider markets. Downstream development includes workshops making simple chocolate directly from farm-grown beans and new market partnerships. Other outputs include the book “Starting from the Farm, Exploring Chocolate Opportunities – A Practical Guide to Cocoa Farming in Papua”, the 2027–2029 Development Plan for the Lereh Agropolitan Area Based on Cocoa as a Leading Commodity, and the Lereh Transmigration Area website. Programme continuity is reinforced by an Agropolitan Working Group led by the Transmigration Office as area development coordinator.", "Manajemen usaha": "Business management", "Program pendampingan manajemen usaha dan tata kelola kelembagaan di wilayah transmigrasi telah dilaksanakan melalui serangkaian kegiatan penguatan kapasitas kelompok tani. Pendampingan diberikan kepada lima kelompok tani, dengan fokus pada peningkatan kemampuan manajemen keuangan dan pengarsipan dokumen. Selain itu, dilaksanakan pelatihan manajemen keuangan, tata kelola kelembagaan, serta pemasaran dan pengemasan produk. Program ini juga memberikan dukungan barang modal untuk menunjang kegiatan produktif kelompok. Melalui rangkaian kegiatan tersebut, diharapkan kelompok tani mampu meningkatkan profesionalisme pengelolaan usaha, memperkuat kelembagaan, meningkatkan daya saing produk, serta mewujudkan kemandirian ekonomi masyarakat secara berkelanjutan.": "Business management and institutional governance support in the transmigration area has included a series of farmer group capacity-building activities. Five farmer groups received mentoring focused on financial management and document archiving. Training also covered finance, institutional governance, marketing, and packaging. Capital equipment support was provided for productive group activities. These efforts aim to improve professional business management, strengthen institutions, increase product competitiveness, and support sustainable community economic independence.", "Memperbaiki nilai hulu kakao": "Strengthening Cocoa's Upstream Value", "Kami mendampingi dan melatih petani kakao pada empat fondasi budidaya yang berkelanjutan: peningkatan sumber daya manusia, penerapan agroforestri, penggunaan klon unggul yang adaptif terhadap perubahan iklim, dan regenerasi petani muda. Tiga sesi pelatihan membahas pascapanen, budidaya yang baik, dan pengendalian hama, dilengkapi lima modul serta brosur praktik pembuatan pupuk dan pestisida nabati. Pelatihan dilakukan bersama pemangku kepentingan dan local champion yang menjadi mitra penting penggerak budidaya kakao di kawasan. Di SP 3, kebun percontohan dibangun dengan pola Diversification Cocoa Agroforestry (DCA) agar petani transmigran maupun masyarakat Lereh dapat belajar langsung dan menerapkannya secara bertahap.": "We mentor and train cocoa farmers in four foundations of sustainable cultivation: human resource development, agroforestry, improved clones adapted to climate change, and the regeneration of young farmers. Three training sessions cover postharvest handling, good cultivation practices, and pest control, supported by five modules and practical leaflets on plant-based fertilisers and pesticides. Training involves stakeholders and local champions who help drive cocoa cultivation in the area. In SP 3, a demonstration farm uses Diversification Cocoa Agroforestry (DCA), enabling transmigrant farmers and Lereh residents to learn directly and adopt practices gradually.", "Putar foto": "Play photos", "Penerimaan": "Revenue", "Produksi": "Production", "Total biaya": "Total cost", "Selisih": "Balance", "Penerimaan/tahun": "Revenue/year", "Total biaya/tahun": "Total cost/year", "Selisih/tahun": "Balance/year", "Titik impas produksi": "Break-even production", "Belum tercapai": "Not reached", "Penerimaan melebihi biaya yang dimasukkan": "Revenue exceeds the entered costs", "Penerimaan belum menutup biaya yang dimasukkan": "Revenue does not cover the entered costs", "Penerimaan sama dengan biaya yang dimasukkan": "Revenue equals the entered costs", "Isi semua kolom dengan angka antara 0 dan 1 triliun.": "Fill in every field with a number between 0 and 1 trillion.", "Lengkapi input untuk melihat hasil.": "Complete the inputs to see the results.", "Titik impas produksi tidak tercapai karena harga jual tidak melebihi biaya variabel per kg.": "Break-even production cannot be reached because selling price does not exceed variable cost per kg.", "Produksi sudah mencapai titik impas pada asumsi ini.": "Production has reached the break-even point under these assumptions.", "Peta jalan": "Street map", "10 titik CPCL/demplot • Klik titik atau pilih lokasi pada daftar. Gunakan tombol +/− untuk memperbesar peta.": "10 CPCL/demonstration plot points • Click a point or select a location. Use +/− to zoom.", "Peta belum dapat dimuat. Daftar lokasi tetap tersedia di bawah.": "The map could not be loaded. The list of locations remains available below.", "Data pasar belum dapat dimuat. Coba muat ulang atau buka sumber harga.": "Market data could not be loaded. Reload the page or open the price source.", "Kakao oleh TradingView": "Cocoa by TradingView", "KAKAO INTERNASIONAL (CFD) · USD/TON": "INTERNATIONAL COCOA (CFD) · USD/TONNE", "Bahasa Indonesia": "Indonesian", "Pilihan bahasa": "Language selection", "Menu utama": "Main menu", "Buka menu": "Open menu", "Tutup menu": "Close menu", "Koordinat:": "Coordinates:", "Lokasi demplot": "Demonstration plot location", "Tidak ada data": "No data", "Tidak tersedia": "Unavailable", "Suhu rata-rata": "Mean temperature", "Suhu minimum": "Minimum temperature", "Suhu maksimum": "Maximum temperature", "Curah hujan": "Rainfall", "Bulan kering": "Dry months", "Kelembapan": "Humidity", "Tekstur tanah": "Soil texture", "Fragmen kasar": "Coarse fragments", "Karbon organik": "Organic carbon", "Nitrogen": "Nitrogen", "Kapasitas tukar kation": "Cation exchange capacity", "pH tanah": "Soil pH", "Sumber": "Source", "Distrik": "District", "Jalan": "Road", "Peta Interaktif Kawasan Lereh": "Lereh Interactive Area Map", "Peta Interaktif Tambahan": "Additional Interactive Map", "Navigasi utama": "Main navigation", "Logo institusi": "Institution logos", "Contoh skenario": "Example scenarios", "Geser produksi biji kering": "Adjust dried bean production", "Geser harga jual": "Adjust selling price", "Geser biaya variabel": "Adjust variable cost", "Geser biaya tetap": "Adjust fixed cost", "Harga acuan kakao internasional": "International cocoa reference price", "Kuotasi kakao internasional dari TradingView": "International cocoa quote from TradingView", "Peta interaktif persebaran demplot kakao": "Interactive cocoa demonstration plot map", "Nindiron Gire, petani kakao di Yapsi": "Nindiron Gire, a cocoa farmer in Yapsi", "Tim Ekspedisi Patriot 1 Lereh": "Lereh Patriot Expedition Team 1", "Kementerian Transmigrasi Republik Indonesia": "Ministry of Transmigration of the Republic of Indonesia"};
(function(){'use strict';
const dictionary=window.LEREH_TRANSLATIONS;delete window.LEREH_TRANSLATIONS;
const normalise=s=>s.replace(/\s+/g,' ').trim();const terms=new Map(Object.entries(dictionary).map(([a,b])=>[normalise(a),b]));
const textState=new WeakMap(),attributeState=new WeakMap();const root=document.documentElement;let language='id',scheduled=false;
const partial=[['kg/tahun','kg/year'],['Rp/tahun','Rp/year'],['Perlu tambahan ','An additional '],[' untuk mencapai titik impas pada asumsi ini.',' is needed to reach break-even under these assumptions.'],['Gunakan harga ','Use price '],['Koordinat: ','Coordinates: '],[' · gambar peta dari playbook',' · map image from the playbook']];
function translated(s){const key=normalise(s);if(terms.has(key)){const leading=s.match(/^\s*/)[0],trailing=s.match(/\s*$/)[0];return leading+terms.get(key)+trailing;}const middle=s.indexOf(' · ');if(middle>0){const first=s.slice(0,middle);if(terms.has(normalise(first)))s=terms.get(normalise(first))+s.slice(middle);}for(const [id,en] of partial)s=s.split(id).join(en);return s;}
function ignored(node){const p=node.parentElement;return !p||Boolean(p.closest('script,style,noscript,code,pre,textarea,.site-language-switch,[translate="no"],.notranslate'));}
function updateText(node){if(ignored(node)||!node.nodeValue.trim())return;const value=node.nodeValue;let state=textState.get(node);if(!state||value!==state.id&&value!==state.en){state={id:value,en:translated(value)};textState.set(node,state);}const next=state[language];if(value!==next)node.nodeValue=next;}
function updateAttributes(el){if(el.closest('.site-language-switch'))return;let values=attributeState.get(el);if(!values){values={};attributeState.set(el,values);}for(const name of ['title','alt','aria-label','placeholder']){const value=el.getAttribute(name);if(!value)continue;let state=values[name];if(!state||value!==state.id&&value!==state.en)state=values[name]={id:value,en:translated(value)};if(state[language]!==value)el.setAttribute(name,state[language]);}}
const observer=new MutationObserver(()=>{if(!scheduled){scheduled=true;queueMicrotask(()=>{scheduled=false;render();});}});
function render(){observer.disconnect();const walker=document.createTreeWalker(document,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode())updateText(n);document.querySelectorAll('[title],[alt],[aria-label],[placeholder]').forEach(updateAttributes);root.lang=language;document.querySelectorAll('.site-language-switch a').forEach(a=>{const code=a.getAttribute('lang');a.setAttribute('aria-current',String(code===language));a.removeAttribute('target');a.removeAttribute('rel');a.title=code==='en'?'View in English':'Lihat dalam bahasa Indonesia';a.setAttribute('aria-label',code==='en'?'English':'Bahasa Indonesia');const url=new URL(location.href);url.searchParams.set('lang',code);a.href=url.pathname+url.search+url.hash;});observer.observe(document,{subtree:true,childList:true,characterData:true});}
function setLanguage(code,remember){language=code==='en'?'en':'id';if(remember){try{localStorage.setItem('lereh-language',language);}catch{}const url=new URL(location.href);url.searchParams.set('lang',language);history.replaceState(null,'',url.pathname+url.search+url.hash);}render();document.dispatchEvent(new CustomEvent('lereh-language-change',{detail:{language}}));}
document.querySelectorAll('.site-language-switch a').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();setLanguage(a.getAttribute('lang'),true);}));
document.addEventListener('click',e=>{const a=e.target.closest&&e.target.closest('a');if(!a||a.closest('.site-language-switch')||a.hasAttribute('download')||a.target==='_blank'||a.getAttribute('href')?.startsWith('#'))return;const url=new URL(a.href,location.href);if(url.origin!==location.origin)return;if(!/\.(html?)$/.test(url.pathname)&&url.pathname!=='/')return;url.searchParams.set('lang',language);a.href=url.pathname+url.search+url.hash;});
let stored='id';try{stored=localStorage.getItem('lereh-language')||'id';}catch{}setLanguage(new URL(location.href).searchParams.get('lang')||stored,false);
})();
